insert into public.food_items (id, slug, name, description, cuisine, meal_types, dietary_tags, allergens, ingredients_complete, spice_level, richness, prep_minutes, cook_minutes, can_cook, can_buy, est_cost_min, est_cost_max, cost_currency, cost_source, serving_qty, serving_unit, serving_grams, calories, protein_g, carbs_g, fat_g, nutrition_source, nutrition_is_estimate, nutrition_confidence, nutrition_notes, image_alt, is_sample) values (md5('food:jollof-rice-chicken')::uuid, 'jollof-rice-chicken', 'Jollof rice with chicken', 'Smoky, tomato-rich party-style jollof with a piece of seasoned chicken.', 'Nigerian', array['lunch','dinner']::text[], array[]::text[], array['celery','mustard','soy','gluten']::text[], true, 2, 2, 20, 50, true, true, 2500, 4500, 'NGN', 'rough_estimate', 1, 'plate', 450, 720, 34, 92, 24, 'reference_estimate', true, 0.5, 'Illustrative reference estimate for a typical home portion. Not laboratory-verified; real values vary with recipe, oil and portion size.', 'A serving of jollof rice with chicken', true) on conflict (slug) do update set name = excluded.name, description = excluded.description, cuisine = excluded.cuisine, meal_types = excluded.meal_types, dietary_tags = excluded.dietary_tags, allergens = excluded.allergens, ingredients_complete = excluded.ingredients_complete, spice_level = excluded.spice_level, richness = excluded.richness, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, can_cook = excluded.can_cook, can_buy = excluded.can_buy, est_cost_min = excluded.est_cost_min, est_cost_max = excluded.est_cost_max, calories = excluded.calories, protein_g = excluded.protein_g, carbs_g = excluded.carbs_g, fat_g = excluded.fat_g;
insert into public.recipes (id, food_item_id, servings, steps, source) values (md5('recipe:jollof-rice-chicken')::uuid, md5('food:jollof-rice-chicken')::uuid, 4, array['Season the chicken with salt, thyme, curry and half an onion, then simmer until just cooked. Keep the stock.','Blend tomatoes, tatashe, scotch bonnet and onion until smooth.','Fry the tomato paste in oil for 3 minutes, add the blend and cook down for 20–25 minutes until thick and no longer sour.','Add stock, bay leaves and seasoning, then stir in washed rice. Cover tightly with foil and a lid.','Cook on low heat for 25–30 minutes, adding small splashes of stock only if needed. Let the base catch slightly for a smoky flavour.','Grill or fry the chicken pieces until golden and serve with the rice.']::text[], 'DISH original') on conflict (food_item_id) do update set servings = excluded.servings, steps = excluded.steps;
