insert into public.recipes (id, food_item_id, servings, steps, source) values (md5('recipe:fried-rice')::uuid, md5('food:fried-rice')::uuid, 4, array['Cook the chicken with thyme and seasoning; reserve the stock.','Parboil rice in the stock with curry powder until just tender, then spread out to dry slightly.','Dice carrots and green beans. Stir-fry briefly in oil with the peas — keep them crisp.','Fry the rice in batches with a little oil, folding in the vegetables and spring onion.','Serve with the chicken, fried or grilled.']::text[], 'DISH original') on conflict (food_item_id) do update set servings = excluded.servings, steps = excluded.steps;
